import { Order } from '../models/Order.js';
import { Product } from '../models/Product.js';

const startOfToday = () => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
};

const daysAgo = (n) => {
  const d = new Date();
  d.setDate(d.getDate() - n);
  d.setHours(0, 0, 0, 0);
  return d;
};

export const getAdminStats = async (_req, res) => {
  try {
    const todayStart = startOfToday();
    const weekStart = daysAgo(7);
    const notCancelled = { status: { $ne: 'cancelled' } };

    const [
      totalOrders,
      ordersToday,
      ordersThisWeek,
      totalProducts,
      revenueAll,
      revenueWeek,
      statusBreakdown,
      recentOrders,
    ] = await Promise.all([
      Order.countDocuments(),
      Order.countDocuments({ createdAt: { $gte: todayStart } }),
      Order.countDocuments({ createdAt: { $gte: weekStart } }),
      Product.countDocuments(),
      Order.aggregate([
        { $match: notCancelled },
        { $group: { _id: null, total: { $sum: '$total' } } },
      ]),
      Order.aggregate([
        { $match: { ...notCancelled, createdAt: { $gte: weekStart } } },
        { $group: { _id: null, total: { $sum: '$total' } } },
      ]),
      Order.aggregate([
        { $group: { _id: '$status', count: { $sum: 1 } } },
      ]),
      Order.find()
        .sort({ createdAt: -1 })
        .limit(5)
        .select('orderNumber total status createdAt paymentStatus')
        .lean(),
    ]);

    const byStatus = Object.fromEntries(
      statusBreakdown.map((row) => [row._id, row.count])
    );

    res.json({
      orders: {
        total: totalOrders,
        today: ordersToday,
        thisWeek: ordersThisWeek,
        byStatus: byStatus,
      },
      revenue: {
        total: revenueAll[0]?.total ?? 0,
        thisWeek: revenueWeek[0]?.total ?? 0,
      },
      products: {
        total: totalProducts,
      },
      recentOrders: recentOrders.map((o) => ({
        id: o._id.toString(),
        orderNumber: o.orderNumber,
        total: o.total,
        status: o.status,
        paymentStatus: o.paymentStatus,
        createdAt: o.createdAt,
      })),
    });
  } catch (error) {
    console.error('getAdminStats error:', error);
    res.status(500).json({ message: 'Failed to load dashboard stats' });
  }
};

import bcrypt from 'bcryptjs';
import { User } from '../models/User.js';
import { formatUser } from '../utils/formatUser.js';
import { signToken } from '../utils/token.js';
import { roleForEmail } from '../utils/adminEmail.js';
import {
  buildResetPasswordUrl,
  generateResetToken,
  getResetTokenExpiry,
  hashResetToken,
} from '../utils/resetPassword.js';
import { isEmailConfigured, sendPasswordResetEmail } from '../services/email.js';

const PASSWORD_RESET_MESSAGE =
  'If an account exists for that email, a password reset link has been sent.';

const sendAuthResponse = (res, user, statusCode = 200) => {
  const token = signToken(user._id);
  res.status(statusCode).json({
    user: formatUser(user),
    token,
  });
};

export const register = async (req, res) => {
  try {
    const { name, email, password } = req.body;

    if (!name?.trim() || !email?.trim() || !password) {
      return res.status(400).json({ message: 'Name, email, and password are required' });
    }

    if (password.length < 6) {
      return res.status(400).json({ message: 'Password must be at least 6 characters' });
    }

    const normalizedEmail = email.trim().toLowerCase();
    const existing = await User.findOne({ email: normalizedEmail });

    if (existing) {
      return res.status(409).json({ message: 'An account with this email already exists' });
    }

    const hashedPassword = await bcrypt.hash(password, 10);

    const user = await User.create({
      name: name.trim(),
      email: normalizedEmail,
      password: hashedPassword,
      role: roleForEmail(normalizedEmail),
    });

    sendAuthResponse(res, user, 201);
  } catch (error) {
    console.error('register error:', error);
    res.status(500).json({ message: 'Failed to register user' });
  }
};

export const login = async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email?.trim() || !password) {
      return res.status(400).json({ message: 'Email and password are required' });
    }

    const user = await User.findOne({ email: email.trim().toLowerCase() }).select('+password');

    if (!user) {
      return res.status(401).json({ message: 'Invalid email or password' });
    }

    const isMatch = await bcrypt.compare(password, user.password);

    if (!isMatch) {
      return res.status(401).json({ message: 'Invalid email or password' });
    }

    sendAuthResponse(res, user);
  } catch (error) {
    console.error('login error:', error);
    res.status(500).json({ message: 'Failed to log in' });
  }
};

export const getMe = async (req, res) => {
  res.json({ user: formatUser(req.user) });
};

export const forgotPassword = async (req, res) => {
  try {
    const { email } = req.body;

    if (!email?.trim()) {
      return res.status(400).json({ message: 'Email is required' });
    }

    const normalizedEmail = email.trim().toLowerCase();
    const user = await User.findOne({ email: normalizedEmail });

    if (user) {
      const rawToken = generateResetToken();
      user.resetPasswordToken = hashResetToken(rawToken);
      user.resetPasswordExpires = getResetTokenExpiry();
      await user.save({ validateBeforeSave: false });

      const resetUrl = buildResetPasswordUrl(rawToken);

      try {
        await sendPasswordResetEmail({
          to: normalizedEmail,
          name: user.name,
          resetUrl,
        });
      } catch (emailError) {
        user.resetPasswordToken = null;
        user.resetPasswordExpires = null;
        await user.save({ validateBeforeSave: false });
        console.error('forgotPassword email error:', emailError);
        return res.status(500).json({
          message: isEmailConfigured()
            ? 'Failed to send reset email. Please try again later.'
            : 'Email is not configured on the server.',
        });
      }
    }

    res.json({ message: PASSWORD_RESET_MESSAGE });
  } catch (error) {
    console.error('forgotPassword error:', error);
    res.status(500).json({ message: 'Failed to process password reset request' });
  }
};

export const resetPassword = async (req, res) => {
  try {
    const { token, password } = req.body;

    if (!token?.trim()) {
      return res.status(400).json({ message: 'Reset token is required' });
    }

    if (!password) {
      return res.status(400).json({ message: 'New password is required' });
    }

    if (password.length < 6) {
      return res.status(400).json({ message: 'Password must be at least 6 characters' });
    }

    const hashedToken = hashResetToken(token.trim());
    const user = await User.findOne({
      resetPasswordToken: hashedToken,
      resetPasswordExpires: { $gt: new Date() },
    }).select('+resetPasswordToken +resetPasswordExpires +password');

    if (!user) {
      return res.status(400).json({ message: 'Invalid or expired reset link' });
    }

    user.password = await bcrypt.hash(password, 10);
    user.resetPasswordToken = null;
    user.resetPasswordExpires = null;
    await user.save();

    res.json({ message: 'Password updated successfully. You can sign in now.' });
  } catch (error) {
    console.error('resetPassword error:', error);
    res.status(500).json({ message: 'Failed to reset password' });
  }
};

import chatbotService from '../services/chatbot.service.js';
import { ChatConversation } from '../models/ChatConversation.js';

/**
 * Chat Controller - Handles chatbot API requests
 */

/**
 * POST /api/chat/message
 * Send a message to the chatbot and get a response
 * Now saves conversation to database
 */
export async function sendMessage(req, res) {
  try {
    const { message, conversationHistory, conversationId } = req.body;

    // Validate message
    if (!message || typeof message !== 'string' || message.trim().length === 0) {
      return res.status(400).json({
        success: false,
        error: 'Message is required and must be a non-empty string',
      });
    }

    // Check message length (max 1000 characters)
    if (message.length > 1000) {
      return res.status(400).json({
        success: false,
        error: 'Message is too long (max 1000 characters)',
      });
    }

    // Get user from request (if authenticated)
    const user = req.user || null;

    // Debug logging
    console.log('💬 Chat message received:');
    console.log('   - User authenticated:', !!user);
    console.log('   - User ID:', user ? user._id : 'null');
    console.log('   - Conversation ID:', conversationId || 'new');
    console.log('   - Authorization header:', req.headers.authorization ? 'present' : 'missing');

    // Validate conversation history if provided
    let history = [];
    if (conversationHistory && Array.isArray(conversationHistory)) {
      // Limit history to last 10 messages to avoid token limits
      history = conversationHistory.slice(-10);
    }

    // Generate AI response
    const response = await chatbotService.generateResponse(
      message.trim(),
      history,
      user
    );

    // Save conversation to database
    let conversation;
    try {
      if (conversationId) {
        // Continue existing conversation
        conversation = await ChatConversation.findById(conversationId);
        if (conversation && conversation.isActive) {
          await conversation.addMessage('user', message.trim());
          await conversation.addMessage('bot', response);
        } else {
          // If conversation not found or deleted, create new one
          const title = ChatConversation.generateTitle(message.trim());
          conversation = new ChatConversation({
            userId: user ? user._id : null,
            title,
            messages: [
              { role: 'user', content: message.trim() },
              { role: 'bot', content: response },
            ],
          });
          await conversation.save();
        }
      } else {
        // Create new conversation
        const title = ChatConversation.generateTitle(message.trim());
        conversation = new ChatConversation({
          userId: user ? user._id : null,
          title,
          messages: [
            { role: 'user', content: message.trim() },
            { role: 'bot', content: response },
          ],
        });
        await conversation.save();
        console.log('✅ New conversation created:', conversation._id);
        console.log('   - userId:', conversation.userId);
      }
    } catch (dbError) {
      console.error('Failed to save conversation:', dbError);
      // Continue even if database save fails
    }

    // Get quick reply suggestions
    const quickReplies = chatbotService.getQuickReplies(message);

    // Return response with conversation ID
    return res.status(200).json({
      success: true,
      data: {
        message: response,
        quickReplies,
        timestamp: new Date().toISOString(),
        conversationId: conversation ? conversation._id : null,
      },
    });
  } catch (error) {
    console.error('Chat controller error:', error);
    return res.status(500).json({
      success: false,
      error: 'Failed to process message. Please try again.',
    });
  }
}

/**
 * GET /api/chat/health
 * Check if chatbot service is available
 */
export async function checkHealth(req, res) {
  try {
    // Check if API key is configured
    if (!process.env.GEMINI_API_KEY) {
      return res.status(503).json({
        success: false,
        status: 'unavailable',
        error: 'Chatbot API key not configured',
      });
    }

    return res.status(200).json({
      success: true,
      status: 'available',
      message: 'Chatbot service is running',
      model: 'gemini-2.5-flash',
    });
  } catch (error) {
    console.error('Chat health check error:', error);
    return res.status(500).json({
      success: false,
      status: 'error',
