import { User } from '../models/User.js';
import { verifyToken } from '../utils/token.js';

/**
 * Require a valid JWT. Blocks the request with 401 if missing or invalid.
 */
export const protect = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader?.startsWith('Bearer ')) {
      return res.status(401).json({ message: 'Not authorized — no token provided' });
    }

    const token = authHeader.split(' ')[1];
    const decoded = verifyToken(token);

    const user = await User.findById(decoded.id).select('-password');

    if (!user) {
      return res.status(401).json({ message: 'User no longer exists' });
    }

    req.user = user;
    next();
  } catch {
    return res.status(401).json({ message: 'Not authorized — invalid or expired token' });
  }
};

/**
 * Attach the user to the request if a valid JWT is present.
 * Does NOT block the request if the token is missing or invalid — continues as guest (req.user = null).
 * Used for endpoints that work for both guests and logged-in users (e.g. chatbot messages).
 */
export const optionalAuth = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader?.startsWith('Bearer ')) {
      req.user = null;
      return next();
    }

    const token = authHeader.split(' ')[1];

    try {
      const decoded = verifyToken(token);
      const user = await User.findById(decoded.id).select('-password');
      req.user = user || null;
    } catch {
      req.user = null;
    }

    next();
  } catch {
    req.user = null;
    next();
  }
};

export const requireAdmin = (req, res, next) => {
  if (req.user?.role !== 'admin') {
    return res.status(403).json({ message: 'Admin access required' });
  }
  next();
};

import mongoose from 'mongoose';

const messageSchema = new mongoose.Schema(
  {
    role: {
      type: String,
      enum: ['user', 'bot'],
      required: true,
    },
    content: {
      type: String,
      required: true,
      trim: true,
    },
    timestamp: {
      type: Date,
      default: Date.now,
    },
  },
  { _id: false }
);

const chatConversationSchema = new mongoose.Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      default: null,
      index: true,
    },
    title: {
      type: String,
      required: true,
      trim: true,
      maxlength: 100,
    },
    messages: {
      type: [messageSchema],
      default: [],
    },
    isActive: {
      type: Boolean,
      default: true,
      index: true,
    },
    lastMessageAt: {
      type: Date,
      default: Date.now,
    },
  },
  {
    timestamps: true,
  }
);

// Index for efficient querying of user's active conversations
chatConversationSchema.index({ userId: 1, isActive: 1, lastMessageAt: -1 });

// Index for guest conversations (cleanup purposes)
chatConversationSchema.index({ userId: 1, createdAt: 1 });

// Virtual for message count
chatConversationSchema.virtual('messageCount').get(function () {
  return this.messages.length;
});

// Method to add a message to the conversation
chatConversationSchema.methods.addMessage = function (role, content) {
  this.messages.push({ role, content, timestamp: new Date() });
  this.lastMessageAt = new Date();
  return this.save();
};

// Method to generate title from first user message
chatConversationSchema.statics.generateTitle = function (firstMessage) {
  const maxLength = 50;
  let title = firstMessage.trim();

  // Remove special characters and extra spaces
  title = title.replace(/[^\w\s]/gi, ' ').replace(/\s+/g, ' ').trim();

  // Truncate if too long
  if (title.length > maxLength) {
    title = title.substring(0, maxLength).trim() + '...';
  }

  // If empty after cleaning, use default
  if (!title) {
    title = 'New Conversation';
  }

  return title;
};

// Method to soft delete conversation
chatConversationSchema.methods.softDelete = function () {
  this.isActive = false;
  return this.save();
};

export const ChatConversation = mongoose.model('ChatConversation', chatConversationSchema);

