const PAYMENT_METHODS = ['upi', 'card', 'netbanking', 'cod'];

export const validateShippingAddress = (address) => {
  const required = [
    'firstName',
    'lastName',
    'email',
    'phone',
    'address',
    'city',
    'state',
    'pincode',
  ];

  for (const field of required) {
    if (!address?.[field]?.trim()) {
      return `Missing required field: ${field}`;
    }
  }

  return null;
};

export const normalizeOrderPayload = (body) => {
  const {
    items,
    shippingAddress,
    paymentMethod,
    subtotal,
    shipping,
    codCharge = 0,
    total,
  } = body;

  if (!items?.length) {
    return { error: 'Cart is empty' };
  }

  if (!PAYMENT_METHODS.includes(paymentMethod)) {
    return { error: 'Invalid payment method' };
  }

  const addressError = validateShippingAddress(shippingAddress);
  if (addressError) {
    return { error: addressError };
  }

  if (
    typeof subtotal !== 'number' ||
    typeof shipping !== 'number' ||
    typeof total !== 'number'
  ) {
    return { error: 'Invalid order totals' };
  }

  const normalizedItems = items.map((item) => ({
    productId: item.productId ?? item.id,
    name: item.name,
    category: item.category,
    size: item.size,
    quantity: item.quantity,
    price: item.price,
  }));

  return {
    data: {
      items: normalizedItems,
      shippingAddress: {
        firstName: shippingAddress.firstName.trim(),
        lastName: shippingAddress.lastName.trim(),
        email: shippingAddress.email.trim().toLowerCase(),
        phone: shippingAddress.phone.trim(),
        address: shippingAddress.address.trim(),
        city: shippingAddress.city.trim(),
        state: shippingAddress.state.trim(),
        pincode: shippingAddress.pincode.trim(),
      },
      paymentMethod,
      subtotal,
      shipping,
      codCharge: codCharge || 0,
      total,
    },
  };
};

import { Order } from '../models/Order.js';
import { notifyOrderConfirmation } from './orderEmail.js';

/**
 * Mark a Razorpay order as paid (idempotent).
 * Sends confirmation email only on first transition to paid.
 */
export const fulfillRazorpayOrder = async (order, razorpayPaymentId) => {
  if (order.paymentStatus === 'paid') {
    return { alreadyPaid: true, order };
  }

  order.status = 'confirmed';
  order.paymentStatus = 'paid';
  order.razorpayPaymentId = razorpayPaymentId;
  await order.save();

  await notifyOrderConfirmation(order);

  return { alreadyPaid: false, order };
};

export const markRazorpayOrderFailed = async (razorpayOrderId, razorpayPaymentId) => {
  const order = await Order.findOne({ razorpayOrderId });

  if (!order || order.paymentStatus === 'paid') {
    return null;
  }

  order.paymentStatus = 'failed';
  if (razorpayPaymentId) {
    order.razorpayPaymentId = razorpayPaymentId;
  }
  await order.save();

  return order;
};

export const findOrderByRazorpayOrderId = (razorpayOrderId) =>
  Order.findOne({ razorpayOrderId });

import crypto from 'crypto';

export const getWebhookSecret = () => process.env.RAZORPAY_WEBHOOK_SECRET?.trim() || '';

export const isWebhookConfigured = () => Boolean(getWebhookSecret());

/** Verify Razorpay webhook signature against raw request body */
export const verifyWebhookSignature = (rawBody, signature) => {
  const secret = getWebhookSecret();
  if (!secret || !signature) return false;

  const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
  return expected === signature;
};

/** Verify checkout payment signature (client callback) */
export const verifyPaymentSignature = (razorpayOrderId, razorpayPaymentId, signature) => {
  const secret = process.env.RAZORPAY_KEY_SECRET;
  if (!secret || !signature) return false;

  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${razorpayOrderId}|${razorpayPaymentId}`)
    .digest('hex');

  return expected === signature;
};

