const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:5000';

/**
 * Chat API - Handles chatbot communication
 */

/**
 * Send a message to the chatbot
 * @param {string} message - User's message
 * @param {Array} conversationHistory - Previous messages (optional)
 * @param {string} conversationId - ID of existing conversation (optional)
 * @returns {Promise<Object>} - Response with AI message and quick replies
 */
export async function sendChatMessage(message, conversationHistory = [], conversationId = null) {
  try {
    const token = localStorage.getItem('flaghouse_token');

    const headers = {
      'Content-Type': 'application/json',
    };

    // Add auth token if user is logged in (optional for chatbot)
    if (token) {
      headers.Authorization = `Bearer ${token}`;
    }

    const response = await fetch(`${API_URL}/api/chat/message`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        message,
        conversationHistory,
        conversationId,
      }),
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || 'Failed to send message');
    }

    return data.data;
  } catch (error) {
    console.error('Chat API error:', error);
    throw error;
  }
}

/**
 * Check if chatbot service is available
 * @returns {Promise<Object>} - Health status
 */
export async function checkChatbotHealth() {
  try {
    const response = await fetch(`${API_URL}/api/chat/health`);
    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || 'Health check failed');
    }

    return data;
  } catch (error) {
    console.error('Chatbot health check error:', error);
    throw error;
  }
}

/**
 * Get all conversations for the authenticated user
 * @param {number} page - Page number (default: 1)
 * @param {number} limit - Items per page (default: 20)
 * @returns {Promise<Object>} - List of conversations with pagination
 */
export async function getConversations(page = 1, limit = 20) {
  try {
    const token = localStorage.getItem('flaghouse_token');

    if (!token) {
      throw new Error('Authentication required');
    }

    const response = await fetch(`${API_URL}/api/chat/conversations?page=${page}&limit=${limit}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || 'Failed to fetch conversations');
    }

    return data.data;
  } catch (error) {
    console.error('Get conversations error:', error);
    throw error;
  }
}

/**
 * Get a specific conversation with all messages
 * @param {string} conversationId - Conversation ID
 * @returns {Promise<Object>} - Conversation with all messages
 */
export async function getConversation(conversationId) {
  try {
    const token = localStorage.getItem('flaghouse_token');

    if (!token) {
      throw new Error('Authentication required');
    }

    const response = await fetch(`${API_URL}/api/chat/conversations/${conversationId}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || 'Failed to fetch conversation');
    }

    return data.data;
  } catch (error) {
    console.error('Get conversation error:', error);
    throw error;
  }
}

/**
 * Delete a conversation (soft delete)
 * @param {string} conversationId - Conversation ID
 * @returns {Promise<Object>} - Success message
 */
export async function deleteConversation(conversationId) {
  try {
    const token = localStorage.getItem('flaghouse_token');

    if (!token) {
      throw new Error('Authentication required');
    }

    const response = await fetch(`${API_URL}/api/chat/conversations/${conversationId}`, {
      method: 'DELETE',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || 'Failed to delete conversation');
    }

    return data;
  } catch (error) {
    console.error('Delete conversation error:', error);
    throw error;
  }
}

