function getConversationEmoji(title) {
  const t = (title || '').toLowerCase();
  if (t.includes('sport') || t.includes('cricket') || t.includes('football') || t.includes('basket')) return '⚽';
  if (t.includes('gaming') || t.includes('game') || t.includes('setup')) return '🎮';
  if (t.includes('music') || t.includes('band') || t.includes('rock')) return '🎵';
  if (t.includes('travel') || t.includes('country') || t.includes('world') || t.includes('map')) return '✈️';
  if (t.includes('ship') || t.includes('deliver') || t.includes('order')) return '📦';
  if (t.includes('price') || t.includes('cost') || t.includes('discount')) return '💰';
  if (t.includes('categor')) return '🛍️';
  if (t.includes('featured') || t.includes('show me')) return '⭐';
  if (t.includes('hello') || t.includes('hi') || t.includes('name')) return '👋';
  if (t.includes('flag')) return '🚩';
  return '💬';
}

function formatTimeAgo(dateString) {
  const diffMs = Date.now() - new Date(dateString).getTime();
  const mins = Math.floor(diffMs / 60000);
  const hours = Math.floor(diffMs / 3600000);
  const days = Math.floor(diffMs / 86400000);
  if (mins < 1) return 'Just now';
  if (mins < 60) return `${mins}m ago`;
  if (hours < 24) return `${hours}hr ago`;
  if (days === 1) return 'Yesterday';
  return new Date(dateString).toLocaleDateString();
}

// Render **bold** and bullet lines from bot markdown-ish responses
function BotMessage({ content }) {
  const lines = (content || '').split('\n');
  return (
    <div className="space-y-0.5">
      {lines.map((line, i) => {
        const isBullet = /^[-•*]\s/.test(line);
        const text = isBullet ? line.replace(/^[-•*]\s/, '') : line;
        const parts = text.split(/(\*\*[^*]+\*\*)/g).map((p, j) =>
          p.startsWith('**') && p.endsWith('**')
            ? <strong key={j}>{p.slice(2, -2)}</strong>
            : p
        );
        if (isBullet) {
          return (
            <div key={i} className="flex gap-1.5">
              <span className="shrink-0 mt-px">•</span>
              <span>{parts}</span>
            </div>
          );
        }
        return <div key={i} className={line === '' ? 'h-1' : ''}>{parts}</div>;
      })}
    </div>
  );
}

// ── Chatbot Component ──────────────────────────────────────────────────────

export default function Chatbot() {
  const { isLoggedIn } = useAuth();

  const [isOpen, setIsOpen] = useState(false);
  // 'conversations' = history list view | 'chat' = active chat view
  const [currentView, setCurrentView] = useState('conversations');

  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [quickReplies, setQuickReplies] = useState([]);
  const [currentConversationId, setCurrentConversationId] = useState(null);

  const [conversations, setConversations] = useState([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);

  // Responsive widget width — full-screen on mobile, fixed 380px on desktop
  const [widgetWidth, setWidgetWidth] = useState(() =>
    typeof window !== 'undefined' ? Math.min(380, window.innerWidth) : 380
  );

  const messagesEndRef = useRef(null);

  const isMobile = widgetWidth < 380;

  // Recompute widget width on resize
  useEffect(() => {
    const compute = () => setWidgetWidth(Math.min(380, window.innerWidth));
    window.addEventListener('resize', compute);
    return () => window.removeEventListener('resize', compute);
  }, []);

  // Load conversations whenever the widget opens (and user is logged in)
  useEffect(() => {
    if (isOpen && isLoggedIn) {
      loadConversations();
    }
  }, [isOpen, isLoggedIn]);

  // Auto-scroll on new messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // ── Data helpers ─────────────────────────────────────────────────────────

  const loadConversations = async () => {
    try {
      setIsLoadingHistory(true);
      const data = await getConversations();
      setConversations(data.conversations);
    } catch (err) {
      console.error('Failed to load conversations:', err);
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const handleLoadConversation = async (conversationId) => {
    try {
      setIsLoadingHistory(true);
      const data = await getConversation(conversationId);
      const loaded = data.conversation.messages.map((m) => ({
        role: m.role === 'user' ? 'user' : 'assistant',
        content: m.content,
        timestamp: m.timestamp,
      }));
      setMessages(loaded);
      setCurrentConversationId(conversationId);
      setQuickReplies([]);
      setCurrentView('chat');
    } catch (err) {
      console.error('Failed to load conversation:', err);
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const handleDeleteConversation = async (conversationId) => {
    if (!confirm('Delete this conversation?')) return;
    try {
      await deleteConversation(conversationId);
      if (conversationId === currentConversationId) {
        setMessages([]);
        setCurrentConversationId(null);
      }
      await loadConversations();
    } catch (err) {
      console.error('Failed to delete conversation:', err);
    }
  };

  const handleNewChat = () => {
    setMessages([]);
    setQuickReplies([]);
    setCurrentConversationId(null);
    setCurrentView('chat');
  };

  const handleSendMessage = async (messageText) => {
    const text = messageText || input.trim();
    if (!text || isLoading) return;

    setInput('');
    setMessages((prev) => [...prev, { role: 'user', content: text, timestamp: new Date().toISOString() }]);
    setIsLoading(true);
    setQuickReplies([]);

    try {
      const history = messages.slice(-10).map((m) => ({ role: m.role, content: m.content }));
      const response = await sendChatMessage(text, history, currentConversationId);
      if (response.conversationId && !currentConversationId) {
        setCurrentConversationId(response.conversationId);
      }
      setMessages((prev) => [
        ...prev,
        { role: 'assistant', content: response.message, timestamp: response.timestamp },
      ]);
      setQuickReplies(response.quickReplies || []);
    } catch {
      setMessages((prev) => [
        ...prev,
        { role: 'assistant', content: "I'm having trouble connecting right now. Please try again! 😊", timestamp: new Date().toISOString() },
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleBackToConversations = () => {
    setCurrentView('conversations');
    if (isLoggedIn) loadConversations();
  };

  // ── Render ───────────────────────────────────────────────────────────────

  return (
    <>
      {/* ── Widget (always mounted so state persists on close/reopen) ────── */}
      <div
        className="fixed z-50 overflow-hidden"
        style={{
          bottom: isMobile ? 0 : 24,
          right: isMobile ? 0 : 24,
          width: isMobile ? '100vw' : widgetWidth,
          // dvh = dynamic viewport height — shrinks when mobile keyboard opens
          height: isMobile ? '100dvh' : 'min(600px, calc(100vh - 90px))',
          borderRadius: isMobile ? 0 : 22,
          background: '#fff',
          boxShadow: isMobile ? 'none' : '0 28px 80px rgba(0,0,0,0.45)',
          opacity: isOpen ? 1 : 0,
          pointerEvents: isOpen ? 'auto' : 'none',
          transform: isOpen ? 'translateY(0) scale(1)' : 'translateY(16px) scale(0.96)',
          transition: 'opacity 0.25s ease, transform 0.25s ease',
        }}
        aria-hidden={!isOpen}
      >
        {/* Sliding container — absolutely fills the widget, 2x wide, shifts left on chat view */}
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            bottom: 0,
            width: widgetWidth * 2,
            display: 'flex',
            transition: 'transform 0.3s cubic-bezier(0.4,0,0.2,1)',
            transform: currentView === 'chat' ? `translateX(-${widgetWidth}px)` : 'translateX(0)',
          }}
        >

          {/* ══════════════════════════════════════════════════════════════
              VIEW 1 — CONVERSATIONS LIST
          ══════════════════════════════════════════════════════════════ */}
          <div style={{ width: widgetWidth, height: '100%', flexShrink: 0, display: 'flex', flexDirection: 'column' }}>

            {/* Header */}
            <div
              className="shrink-0 px-5 pt-5 pb-4"
              style={{ background: '#111827' }}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  {/* Avatar */}
                  <div
                    className="w-11 h-11 rounded-full flex items-center justify-center text-2xl"
                    style={{ background: 'rgba(255,255,255,0.12)' }}
                  >
                    🤖
                  </div>
                  <div>
                    <p className="text-white font-bold text-sm leading-tight">FlagBot</p>
                    <p className="text-gray-400 text-xs">Your flag shopping assistant</p>
                  </div>
                </div>
                {/* Close */}
                <button
                  onClick={() => setIsOpen(false)}
                  className="w-8 h-8 rounded-full flex items-center justify-center text-white text-sm transition-colors hover:bg-white/10"
                  style={{ background: 'rgba(255,255,255,0.08)' }}
                  aria-label="Close"
                >
                  ✕
                </button>
              </div>

              {/* New conversation CTA */}
              <button
                onClick={handleNewChat}
                className="mt-4 w-full py-2.5 rounded-xl text-white text-sm font-medium transition-colors hover:bg-white/15"
                style={{ background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.15)' }}
              >
                + Start New Conversation
              </button>
            </div>

            {/* Body */}
            <div className="flex-1 overflow-y-auto" style={{ background: '#f9fafb' }}>
              {!isLoggedIn ? (
                <div className="flex flex-col items-center justify-center h-full gap-3 px-8 text-center">
                  <div className="text-5xl">🔒</div>
                  <p className="text-gray-700 font-semibold">Sign in to view history</p>
                  <p className="text-gray-400 text-xs leading-relaxed">
                    Your past conversations will appear here once you're logged in
                  </p>
                </div>
              ) : isLoadingHistory ? (
                <div className="flex items-center justify-center h-32">
                  <div
                    className="w-6 h-6 rounded-full border-2 animate-spin"
                    style={{ borderColor: '#111827', borderTopColor: 'transparent' }}
                  />
                </div>
              ) : conversations.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full gap-3 px-8 text-center">
                  <div className="text-5xl">💬</div>
                  <p className="text-gray-700 font-semibold">No conversations yet</p>
                  <p className="text-gray-400 text-xs">
                    Start a new conversation to see it here
                  </p>
                </div>
              ) : (
                <div className="p-4">
                  <p
                    className="text-xs font-semibold tracking-widest mb-3 px-1"
                    style={{ color: '#9ca3af', letterSpacing: '0.1em' }}
                  >
                    RECENT CONVERSATIONS
                  </p>
                  <div className="space-y-2">
                    {conversations.map((conv) => (
                      <div
                        key={conv.id}
                        onClick={() => handleLoadConversation(conv.id)}
                        className="flex items-center gap-3 p-3 rounded-2xl cursor-pointer transition-colors group"
                        style={{ background: conv.id === currentConversationId ? '#f3f4f6' : '#fff' }}
                        onMouseEnter={(e) => {
                          if (conv.id !== currentConversationId)
                            e.currentTarget.style.background = '#f9fafb';
                        }}
                        onMouseLeave={(e) => {
                          if (conv.id !== currentConversationId)
                            e.currentTarget.style.background = '#fff';
                        }}
                      >
                        {/* Emoji tile */}
                        <div
                          className="w-11 h-11 shrink-0 flex items-center justify-center text-xl rounded-[13px]"
                          style={{ background: '#f3f4f6' }}
                        >
                          {getConversationEmoji(conv.title)}
                        </div>

                        {/* Text */}
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-semibold text-gray-900 truncate">{conv.title}</p>
                          <p className="text-xs text-gray-500 truncate mt-0.5">{conv.lastMessage}</p>
                          <p className="text-xs mt-1" style={{ color: '#9ca3af' }}>
                            {formatTimeAgo(conv.lastMessageAt)} · {conv.messageCount} messages
                          </p>
                        </div>

                        {/* Delete on hover / chevron otherwise */}
                        <div className="shrink-0 relative w-5 h-5">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              e.preventDefault();
                              handleDeleteConversation(conv.id);
                            }}
                            className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity text-red-400 hover:text-red-600"
                            aria-label="Delete conversation"
