import { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { fetchMe } from '../api/auth';

const AuthContext = createContext(null);

const TOKEN_KEY = 'flaghouse_token';
const USER_KEY = 'flaghouse_user';

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    try {
      const saved = localStorage.getItem(USER_KEY);
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });

  const [token, setToken] = useState(() => localStorage.getItem(TOKEN_KEY));
  const [authLoading, setAuthLoading] = useState(!!localStorage.getItem(TOKEN_KEY));

  const logout = useCallback(() => {
    setUser(null);
    setToken(null);
    localStorage.removeItem(USER_KEY);
    localStorage.removeItem(TOKEN_KEY);
  }, []);

  const loginSession = useCallback((userData, authToken) => {
    setUser(userData);
    setToken(authToken);
    localStorage.setItem(USER_KEY, JSON.stringify(userData));
    localStorage.setItem(TOKEN_KEY, authToken);
  }, []);

  const refreshUser = useCallback(async () => {
    if (!token) return null;
    const data = await fetchMe(token);
    setUser(data.user);
    localStorage.setItem(USER_KEY, JSON.stringify(data.user));
    return data.user;
  }, [token]);

  useEffect(() => {
    if (!token) {
      setAuthLoading(false);
      return;
    }

    fetchMe(token)
      .then((data) => {
        setUser(data.user);
        localStorage.setItem(USER_KEY, JSON.stringify(data.user));
      })
      .catch(() => {
        logout();
      })
      .finally(() => {
        setAuthLoading(false);
      });
  }, [token, logout]);

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        loginSession,
        refreshUser,
        logout,
        isLoggedIn: !!user && !!token,
        isAdmin: user?.role === 'admin',
        authLoading,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used inside AuthProvider');
  return ctx;
};

import { createContext, useContext, useState, useEffect } from 'react';
import { resolveProductImage } from '../utils/productImage';

const CartContext = createContext(null);

export const CartProvider = ({ children }) => {
  const [cartItems, setCartItems] = useState(() => {
    try {
      const saved = localStorage.getItem('flaghouse_cart');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  // Persist cart to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('flaghouse_cart', JSON.stringify(cartItems));
  }, [cartItems]);

  // Add item — if same product + size exists, increment quantity
  const addToCart = (product, size = 'Medium (3×5 ft)', quantity = 1) => {
    setCartItems((prev) => {
      const existing = prev.find(
        (item) => item.id === product.id && item.size === size
      );
      if (existing) {
        return prev.map((item) =>
          item.id === product.id && item.size === size
            ? { ...item, quantity: item.quantity + quantity }
            : item
        );
      }
      return [
        ...prev,
        {
          id:            product.id,
          name:          product.name,
          category:      product.category,
          price:         product.price,
          originalPrice: product.originalPrice || null,
          image:         resolveProductImage(product),
          size,
          quantity,
        },
      ];
    });
  };

  // Remove item by id + size
  const removeFromCart = (id, size) => {
    setCartItems((prev) =>
      prev.filter((item) => !(item.id === id && item.size === size))
    );
  };

  // Update quantity — remove if qty drops to 0
  const updateQuantity = (id, size, newQty) => {
    if (newQty < 1) {
      removeFromCart(id, size);
      return;
    }
    setCartItems((prev) =>
      prev.map((item) =>
        item.id === id && item.size === size
          ? { ...item, quantity: newQty }
          : item
      )
    );
  };

  // Clear entire cart
  const clearCart = () => setCartItems([]);

  // Derived values
  const cartCount   = cartItems.reduce((sum, item) => sum + item.quantity, 0);
  const cartSubtotal = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return (
    <CartContext.Provider
      value={{
        cartItems,
        cartCount,
        cartSubtotal,
        addToCart,
        removeFromCart,
        updateQuantity,
        clearCart,
      }}
    >
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error('useCart must be used inside CartProvider');
  return ctx;
};

