const OrdersPage = () => {
  const { token } = useAuth();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const loadOrders = () => {
    if (!token) return;

    setLoading(true);
    setError(null);

    fetchMyOrders(token)
      .then(setOrders)
      .catch((err) => setError(err.message || 'Failed to load orders'))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadOrders();
  }, [token]);

  return (
    <div className="w-full px-4 sm:px-8 py-8 sm:py-10">
      <div className="mb-6 sm:mb-8">
        <h1 className="text-2xl sm:text-4xl font-bold text-gray-900 mb-1">My Orders</h1>
        <p className="text-sm sm:text-base text-gray-500">Track and review your past FlagHouse orders</p>
      </div>

      {loading && <ProductLoadState message="Loading your orders..." />}

      {error && !loading && (
        <ProductErrorState message={error} onRetry={loadOrders} />
      )}

      {!loading && !error && orders.length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 gap-4 text-center">
          <span className="text-5xl">📦</span>
          <h2 className="text-2xl font-bold text-gray-900">No orders yet</h2>
          <p className="text-base text-gray-500 max-w-sm">
            When you place an order, it will show up here with full details.
          </p>
          <Link
            to="/shop"
            className="mt-2 bg-black text-white font-semibold text-base px-8 py-3 rounded-xl hover:bg-neutral-800 transition-colors"
          >
            Start Shopping
          </Link>
        </div>
      )}

      {!loading && !error && orders.length > 0 && (
        <div className="flex flex-col gap-6 w-full max-w-3xl">
          {orders.map((order) => (
            <OrderCard key={order.id} order={order} />
          ))}
        </div>
      )}
