const ProductDetailPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { isLoggedIn } = useAuth();
  const { addToCart } = useCart();

  const [product, setProduct] = useState(null);
  const [relatedProducts, setRelatedProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedSize, setSelectedSize] = useState(PRODUCT_SIZES[1]);
  const [quantity, setQuantity] = useState(1);
  const [addedToCart, setAddedToCart] = useState(false);
  const [activeImg, setActiveImg] = useState(0);

  const loadProduct = () => {
    setLoading(true);
    setError(null);
    fetchProductById(id)
      .then((data) => {
        setProduct(data.product);
        setRelatedProducts(data.related || []);
      })
      .catch((err) => setError(err.message || 'Failed to load product'))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadProduct();
    setActiveImg(0);
  }, [id]);

  const handleAddToCart = () => {
    if (!product) return;
    addToCart(product, selectedSize, quantity);
    setAddedToCart(true);
    setTimeout(() => setAddedToCart(false), 2000);
  };

  const handleBuyNow = () => {
    if (!product) return;
    addToCart(product, selectedSize, quantity);
    if (isLoggedIn) {
      navigate('/checkout');
    } else {
      navigate('/login', { state: { from: '/checkout' } });
    }
  };

  if (loading) {
    return (
      <div className="w-full px-8 py-10">
        <ProductLoadState message="Loading product..." />
      </div>
    );
  }

  if (error || !product) {
    return (
      <div className="w-full px-8 py-10">
        <ProductErrorState
          message={error || 'Product not found'}
          onRetry={loadProduct}
        />
        <div className="text-center mt-4">
          <Link to="/shop" className="text-sm font-medium text-gray-900 underline">
            Back to shop
          </Link>
        </div>
      </div>
    );
  }

  const discount = product.originalPrice
    ? Math.round((1 - product.price / product.originalPrice) * 100)
    : null;

  return (
    <div className="w-full px-4 sm:px-8 py-8 sm:py-10">

